def dedupe(rows: list[dict], key: str) -> list[dict]:
    seen = set()
    result = []
    for row in rows:
        if key not in row:
            result.append(row)
        else:
            value = row[key]
            if value not in seen:
                seen.add(value)
                result.append(row)
    return result
```

